package io.fireflysoftware.core.product.core.services.definition;

import static org.junit.jupiter.api.Assertions.*;
import io.fireflysoftware.core.product.core.services.definition.impl.*;
import io.fireflysoftware.core.product.models.repositories.definition.lifecycle.ProductDefinitionCommandPersistence;
import io.r2dbc.pool.*;
import java.lang.reflect.*;
import java.time.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.LongSupplier;
import org.fireflyframework.security.api.domain.Decision;
import org.junit.jupiter.api.Test;
import org.springframework.context.support.GenericApplicationContext;
import org.springframework.data.r2dbc.core.DefaultReactiveDataAccessStrategy;
import org.springframework.data.r2dbc.dialect.PostgresDialect;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.Mono;

/** Normal denied current authority; no manufactured private-read or native-success source. */
class TermPcPrivateReadBindingTest {
    final TermPcLifecycleProfileTest source=new TermPcLifecycleProfileTest();
    Object service(boolean review,ProductDefinitionCommandAuthorizationImpl auth,ProductDefinitionCommandPersistence p,GovernedDefinitionProfile backend){try{return (review?ProductDefinitionReviewReadServiceImpl.class:ProductDefinitionCostReadServiceImpl.class).getConstructor(review?ProductDefinitionReviewAuthorization.class:ProductDefinitionCostReadAuthorization.class,ProductDefinitionCommandPersistence.class,GovernedDefinitionProfile.class,Clock.class,LongSupplier.class).newInstance(auth,p,backend,Clock.fixed(TermPcLifecycleProfileTest.NOW,ZoneOffset.UTC),(LongSupplier)()->0);}catch(InvocationTargetException e){if(e.getCause()instanceof RuntimeException r)throw r;throw new AssertionError(e.getCause());}catch(ReflectiveOperationException e){throw new AssertionError("Bounded profile-bound private read constructor missing",e);}}
    ProductDefinitionCommandPersistence persistence(ConnectionPool pool,GenericApplicationContext c,boolean bounded){return new ProductDefinitionCommandPersistence(pool,new DefaultReactiveDataAccessStrategy(PostgresDialect.INSTANCE).getConverter(),c,bounded);}
    @Test void newPrivateReadConstructorsRefuseLegacyUnboundedFactory(){for(boolean review:new boolean[]{false,true}){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(GovernedDefinitionProfile.TERM_PC_INSURANCE.policyProfile(),GovernedDefinitionProfile.TERM_PC_INSURANCE,(p,a,r,x)->Mono.just(Decision.deny("DENIED")));assertThrows(IllegalArgumentException.class,()->service(review,auth,persistence(pool,c,false),GovernedDefinitionProfile.TERM_PC_INSURANCE));assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}}
    @Test void privateReadAuthorityMustMatchImmutableBackend(){for(boolean review:new boolean[]{false,true}){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(ProductDefinitionCommandAuthorization.POLICY_PROFILE,GovernedDefinitionProfile.ACCOUNT_TARIFF,(p,a,r,x)->Mono.just(Decision.deny("DENIED")));assertThrows(IllegalArgumentException.class,()->service(review,auth,persistence(pool,c,true),GovernedDefinitionProfile.TERM_PC_INSURANCE));assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}}
    @Test void termPcPrivateCostCurrentDenialDoesNotAcquireDatabase(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var calls=new AtomicInteger();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(GovernedDefinitionProfile.TERM_PC_INSURANCE.policyProfile(),GovernedDefinitionProfile.TERM_PC_INSURANCE,(p,a,r,x)->{assertEquals("TERM_PC_INSURANCE_V1",x.get("profileCode"));calls.incrementAndGet();return Mono.just(Decision.deny("DENIED"));});var view=(ProductDefinitionCostReadService)service(false,auth,persistence(pool,c,true),GovernedDefinitionProfile.TERM_PC_INSURANCE);var e=assertThrows(ResponseStatusException.class,()->view.readCurrent(TermPcLifecycleProfileTest.TENANT,TermPcLifecycleProfileTest.ROOT).block());assertEquals(403,e.getStatusCode().value());assertEquals(1,calls.get());assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void termPcExactAndCurrentSelectionDenialDoesNotAcquireDatabase(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var calls=new AtomicInteger();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(GovernedDefinitionProfile.TERM_PC_INSURANCE.policyProfile(),GovernedDefinitionProfile.TERM_PC_INSURANCE,(p,a,r,x)->{assertEquals("TERM_PC_INSURANCE_V1",x.get("profileCode"));calls.incrementAndGet();return Mono.just(Decision.deny("DENIED"));});var view=(ProductDefinitionReviewReadService)service(true,auth,persistence(pool,c,true),GovernedDefinitionProfile.TERM_PC_INSURANCE);assertThrows(ResponseStatusException.class,()->view.readCurrentSelection(TermPcLifecycleProfileTest.TENANT,TermPcLifecycleProfileTest.ROOT).block());assertThrows(ResponseStatusException.class,()->view.readSelection(TermPcLifecycleProfileTest.TENANT,TermPcLifecycleProfileTest.ROOT,new java.util.UUID(0,3)).block());assertEquals(2,calls.get());assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
}
